    "src/FablesRamp.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.26;

import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {Hooks} from "v4-core/src/libraries/Hooks.sol";
import {PoolKey} from "v4-core/src/types/PoolKey.sol";
import {PoolId, PoolIdLibrary} from "v4-core/src/types/PoolId.sol";
import {FablesLedger} from "./base/FablesLedger.sol";
import {FablesBaseHook} from "./base/FablesBaseHook.sol";

/// @title FablesRamp
/// @notice The unified non-calendar fee hook. One singleton serves every non-equity pool —
///         memecoin, blue-chip, token-issuer — each as a per-pool FLAT fee with a bounded, TTL-
///         expiring operator override (`pokeFee` on the base hook). There is no autonomous dynamic
///         fee: a pool charges its configured `flatPips`, and any responsiveness is applied off-chain
///         and poked on top within a band strictly inside `[floorPips, cap]` — the block below gives
///         the real floor, which a poke cannot go under.
/// @dev WHY NO ON-CHAIN VOLATILITY FEE. An earlier design priced the fee off realized volatility (a
///      Parkinson tick-range estimator, `VolLib`). It was measured against real data and removed. A
///      price-derived estimator can only read realized volatility from the pool's OWN series, and
///      that has two dead ends: for memecoins it saturates, so the ramp pins at its ceiling and is a
///      flat fee in all but name; for blue-chips the quantity that actually matters — LVR / adverse
///      selection against the external mid — is invisible without an ORACLE. A flat fee plus an
///      oracle-driven off-chain poke is both simpler and strictly better where it matters, so the
///      estimator (and the sell-surcharge / quote-orientation machinery it carried) is gone.
///
///      The floor / flat / cap are per-pool and admin-adjustable within the deployment's absolute
///      ceiling, so calibration is a config change, not a redeploy. The poke can only ever move the
///      live fee inside `[max(floorPips, min(preFee, cap)/2), cap]` and lapses back to `flatPips` on
///      expiry, where `preFee` is `flatPips + premiumPips` in the premium direction and `flatPips`
///      in the other. The direction matters and this line used to state the premium term
///      unconditionally: `_resolveFee` computes the discount floor from `preFee`, so on the
///      NON-premium side the real floor is `max(floorPips, min(flatPips, cap)/2)`. A keeper
///      composing the non-premium side from the unconditional form gets a floor that is too high —
///      the safe direction, but wrong, and the old parenthetical made it sound as though the term
///      always applied.
///
///      A keeper failure is benign regardless: the flat is the fee the pool really charges when
///      unattended.
contract FablesRamp is FablesLedger {
    using PoolIdLibrary for PoolKey;

    error InvalidConfig();

    event PoolConfigured(PoolId indexed poolId, uint24 floorPips, uint24 flatPips, uint24 maxFee);

    /// @notice The flat fee (pips) each pool charges autonomously, before any poke and the cap.
    mapping(PoolId poolId => uint24 flatPips) internal _flatPips;

    constructor(IPoolManager poolManager_, address authority_, uint24 absoluteMaxFee_)
        FablesBaseHook(poolManager_, authority_, absoluteMaxFee_)
    {}

    function _hookPermissions() internal pure virtual override returns (Hooks.Permissions memory permissions) {
        permissions.beforeInitialize = true;
        permissions.beforeSwap = true;
    }

    /// @notice The flat fee configured for a pool, in pips.
    function flatFee(PoolId poolId) external view returns (uint24) {
        return _flatPips[poolId];
    }

    /// @notice Registers or updates a pool's flat fee and its poke bounds. `floorPips` is the
    ///         cheapest a poke may reach, `flatPips` the fee charged with no live poke, `cap` the
    ///         ceiling; a poke never escapes `[floorPips, cap]` and expires back to `flatPips`.
    function setPoolConfig(PoolKey calldata key, uint24 floorPips, uint24 flatPips, uint24 cap) external restricted {
        _checkOwnPool(key);
        if (flatPips < floorPips || flatPips > cap) revert InvalidConfig();
        PoolId poolId = key.toId();
        _flatPips[poolId] = flatPips;
        // Also validates floorPips >= MIN_POOL_FEE, floorPips <= cap <= ABSOLUTE_MAX_FEE.
        _setPoolBounds(poolId, floorPips, cap);
        emit PoolConfigured(poolId, floorPips, flatPips, cap);
    }

    /// @notice The autonomous fee is simply the pool's flat rate; the base resolver applies the poke
    ///         override and the cap on top.
    function _autonomousFee(PoolId poolId, IPoolManager.SwapParams memory) internal view override returns (uint256) {
        return _flatPips[poolId];
    }
}
"
    },
    "src/base/LedgerTypes.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.26;

import {PoolKey} from "v4-core/src/types/PoolKey.sol";
import {PoolId} from "v4-core/src/types/PoolId.sol";
import {Currency} from "v4-core/src/types/Currency.sol";

/// @title LedgerTypes
/// @notice Shared ledger types split into their own file so `FablesLedger` and its inlined
///         helper library `LedgerLib` can both reference `RangeState` without a circular import. The
///         struct layout is unchanged from when it lived inside the ledger, so storage is
///         identical; moving the declaration touches no slot.
struct RangeState {
    uint128 totalShares;
    uint128 totalStaked;
    uint256 accFee0X128; // fee per unstaked share, Q128
    uint256 accFee1X128;
    /// @dev Fee per STAKED share, Q128 — the fees staked shares gave up. This is the
    ///      emission weight. Within a pool, fee growth per unit of liquidity is identical
    ///      for every in-range position at any instant, so this quantity IS in-range
    ///      liquidity-seconds, measured in the units that matter. A position the price
    ///      never reaches accrues exactly zero here, which is the whole point.
    uint256 accStaked0X128;
    uint256 accStaked1X128;
    /// @dev Sub-unit remainder left over by the staked-cut division, carried into the next
    ///      window so no accrual can be truncated away by splitting it across syncs. Held as
    ///      a FRACTION of one fee unit in Q128, never as a numerator over `totalShares`:
    ///      see `LedgerLib._takeStakedCut` for why the denominator must not appear here.
    uint128 stakedResidual0;
    uint128 stakedResidual1;
    /// @dev Emitted-collection counter (H6) and zero-liquidity-crossing counter (H2). Both are
    ///      settlement anchors, not accounting: see the `FeesCollected` params. They share a slot.
    uint64 collectionSeq;
    uint64 resetSeq;
}

/// @notice One claim-fee rate and the moment it took effect. Shared with `LedgerLib`, which walks
///         the history to price a range's backlog inside `creditFees`.
struct ClaimFeeChange {
    uint64 fromTs;
    uint16 bps;
}

/// @dev The two things `poolManager.unlock` calls back to do, decoded in `LedgerLib.onUnlock`.
enum Action {
    MODIFY,
    PAYOUT
}

/// @dev A liquidity-modify unlock: apply `liquidityDelta` to the range and settle principal + fees.
///
///      `amount0Limit`/`amount1Limit` carry the CALLER'S CONSENT to the only place that can enforce
///      it. A liquidity quantity does not say what it costs — the token amounts come out of the
///      pool's live price inside `modifyLiquidity` — so without these the settled principal was
///      whatever the price happened to make it, pulled from the caller with no ceiling. On a
///      deposit they are the MOST the caller will pay per currency; on a withdraw, the LEAST they
///      will accept. Ignored entirely when `liquidityDelta == 0` (an internal fee sync moves no
///      principal).
struct CallbackData {
    PoolKey key;
    int24 tickLower;
    int24 tickUpper;
    int256 liquidityDelta;
    address user;
    uint128 amount0Limit;
    uint128 amount1Limit;
}

/// @dev A payout unlock: redeem held claims into real tokens for `to`, kept off the withdraw path.
struct PayoutData {
    Currency currency0;
    Currency currency1;
    uint256 amount0;
    uint256 amount1;
    address to;
}

/// @dev Emitted when accrued staked-share revenue is pushed to the distributor (or the FF sink).
///      File-level so `LedgerLib.sweepDistributor` emits it with the identical
///      signature the settlement indexer reads.
event DistributorSwept(Currency indexed currency, address indexed distributor, uint256 amount);

/// @dev Mirrors `DistributorSwept` for the claim-fee sink. Its absence was a hole in the indexer's
///      reconstruction of the fee split, which is derived from logs alone.
event ClaimFeeSwept(Currency indexed currency, address indexed recipient, uint256 amount);

/// @dev The claim-fee cut taken out of ONE range's collection, at the rate that stood while those
///      fees accrued. This is the only moment that rate is knowable off-chain: `LedgerLib.creditFees`
///      rolls `claimFeeSyncIndex[rangeId]` forward on EVERY sync, including the zero-fee ones that
///      emit nothing at all, so a log reader cannot reconstruct `sinceIndex` and therefore cannot
///      price the cut after the fact. `FeesCollected` already makes the DISTRIBUTOR side per-range
///      attributable through `stakedCut0/1`; this MAKES THE SAME HOLE CLOSABLE on the claim side —
///      not closed, which is what this line used to say. Nothing consumes it: a grep across
///      `indexer/src`, `indexer/runner`, `indexer/ops`, the subgraph mapping, its manifest and its
///      `FablesLedger` ABI returns no reference, so per-pool claim-fee revenue is still not
///      attributed anywhere. No money is at risk (`claimFeeOwed` is keyed by currency and swept
///      whole to one hook-wide recipient, so this is reporting only), but the same round that added
///      `sweepReconciliation` to fix four orphaned events — `DistributorSwept`, `ClaimFeeSwept` and
///      both native wrap events, all with zero consumers — emitted a fifth. Closing it is one
///      subgraph handler; until that exists, the claim above overstates what shipped. Emitted
///      only when a cut is actually taken, so a ledger resting at a zero rate pays no gas for it.
///      `poolId` is indexed because one hook may serve many pools: a per-pool revenue reader then
///      needs no `rangeKey` round-trip, which also keeps attribution working against a non-archive
///      RPC, where the historical read fails outright.
event ClaimFeeAccrued(uint256 indexed rangeId, PoolId indexed poolId, uint256 cut0, uint256 cut1, uint16 feeBps);

/// @dev One pool's claim-fee policy. Bundled so the per-pool rate, its walk floor and its rate
///      history travel as ONE storage handle through the unlock plumbing: the previous shape
///      passed a bare `ClaimFeeChange[]` plus two scalars, and splitting those per pool would have
///      added three parameters to frames that already documented stack-too-deep pressure.
struct PoolClaimFee {
    /// @dev Current rate for this pool. An UPPER bound on what any backlog pays, never a floor.
    uint16 bps;
    /// @dev Lowest rate this POOL has ever stood at; the fallback once a backlog outruns the walk.
    uint16 allTimeMin;
    /// @dev Every rate this pool has stood at, oldest first.
    ClaimFeeChange[] history;
}

struct UserPosition {
    uint128 staked;
    uint128 owed0;
    uint128 owed1;
    uint256 checkpoint0X128;
    uint256 checkpoint1X128;
    uint256 stakedCheckpoint0X128;
    uint256 stakedCheckpoint1X128;
    /// @notice Cumulative fees this holder's STAKED shares gave up, per currency. The basis
    ///         for their emission share within the pool — settlement buckets the deltas by
    ///         epoch from `FeesForgone`, and this running total is the on-chain anchor
    ///         anyone can check a root against.
    uint256 forgone0;
    uint256 forgone1;
}

/// @dev The emission weight, emitted per holder as it accrues. Settlement buckets these by
///      epoch to split a pool's vote-won emissions among the LPs who actually earned them.
///      File-level so `LedgerLib` emits it with the identical signature the
///      settlement indexer already reads.
event FeesForgone(address indexed owner, uint256 indexed rangeId, uint256 amount0, uint256 amount1);

/// @dev Range descriptor, stored on first deposit so paths without a PoolKey argument (ERC-6909
///      transfers) can still sync the pool's lazily-accrued fees first. File-level so `LedgerLib`
///      can read a range's `feeGrowthInside` for the `FeesCollected` emit.
struct RangeKey {
    PoolKey key;
    int24 tickLower;
    int24 tickUpper;
    bool set;
}

/// @dev Emitted on every fee collection so the split between voters (staked) and holders
///      (unstaked) is reproducible from logs — the epoch-settlement trust model assumes exactly
///      that. File-level so `LedgerLib` emits it with the identical signature the
///      indexer reads.
///
///      Carries the per-staked-share accumulator LEVELS, which is what makes emission weight
///      attributable in time. `FeesForgone` fires when a holder is settled, and a settle can be
///      triggered by anyone (a dust transfer settles the receiver) at any block — so its timestamp
///      says when someone poked the position, not when the fees were earned. These levels move only
///      inside the collection itself, so integrating them against the Staked/Unstaked timeline
///      gives each holder's weight per epoch regardless of when anyone settles.
///
///      `feeGrowthInside0X128`/`1X128` are v4's own per-liquidity accumulator for the range, read at
///      the instant of collection: a week's forgone fees become a function of what the position
///      GENERATED rather than of when somebody collected it, so settlement can split a segment that
///      straddles a week boundary AT the boundary, identically for every holder. `totalShares`/
///      `totalStaked` carry the staked fraction rather than reconstructing it. `collectionSeq`
///      increments on EVERY emitted collection, so a DROPPED log is a visible gap and its epoch is
///      quarantined rather than under-paid (H6); `resetSeq` increments whenever the range's v4
///      position crosses zero liquidity in EITHER direction — the deterministic re-base signal that
///      replaced the indexer's steerable magnitude heuristic (H2).
event FeesCollected(
    uint256 indexed rangeId,
    uint256 fee0,
    uint256 fee1,
    uint256 stakedCut0,
    uint256 stakedCut1,
    uint256 accStaked0X128,
    uint256 accStaked1X128,
    uint256 feeGrowthInside0X128,
    uint256 feeGrowthInside1X128,
    uint128 totalShares,
    uint128 totalStaked,
    uint64 collectionSeq,
    uint64 resetSeq
);
"
    },
    "src/base/FablesLedger.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.26;

import {IPoolManager} from "v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {PoolKey} from "v4-core/src/types/PoolKey.sol";
import {PoolId, PoolIdLibrary} from "v4-core/src/types/PoolId.sol";
import {StateLibrary} from "v4-core/src/libraries/StateLibrary.sol";
import {Currency, CurrencyLibrary} from "v4-core/src/types/Currency.sol";
import {ERC6909} from "v4-core/src/ERC6909.sol";
import {ReentrancyGuardTransient} from "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";
import {FablesBaseHook} from "./FablesBaseHook.sol";
import {
    RangeState,
    UserPosition,
    RangeKey,
    ClaimFeeChange,
    PoolClaimFee,
    Action,
    CallbackData,
    PayoutData,
    FeesForgone,
    FeesCollected,
    DistributorSwept,
    ClaimFeeSwept
} from "./LedgerTypes.sol";
import {LedgerLib} from "../libraries/LedgerLib.sol";

/// @title FablesLedger
/// @notice Per-range liquidity ledger inside the singleton hook: users deposit concentrated
///         liquidity in any tick range; the hook holds one PoolManager position per range and
///         mints ERC-6909 receipts 1:1 with liquidity units.
/// @dev Founding constraints, in order of importance:
///       - WITHDRAWALS ARE UNCONDITIONAL. No admin state can BLOCK the path: no pause, no oracle,
///         no distributor, no claim fee on principal; staked shares auto-unstake. It does READ
///         three admin-written values — `claimFeeRecipient` and the per-pool rate in
///         `_poolClaimFee` (which set the skim taken at collection, i.e. the AMOUNT credited), and
///         `maxFee[poolId]` in `_checkKey` (which `_setPoolBounds` can never return to zero). The
///         storage declaration and `withdrawAndClaim` both say this; this line used to claim the
///         path "reads no admin state" flatly, which is the shape that lets a reader conclude the
///         one-way `claimFeeRecipient` guard and `claimFeeFor`'s min-over-window are not
///         load-bearing here.
///         It also makes no token call on the ledger's own behalf: collected fees settle as
///         PoolManager ERC-6909 claims, never as transfers to this contract. A token that
///         blocklists THIS contract therefore cannot freeze anyone's principal, and the only
///         transfer on the path is the PoolManager paying the withdrawer directly.
///       - SOLVENT BY CONSTRUCTION. Shares are liquidity units (no exchange rate), so
///         totalShares(range) == position liquidity is an invariant, not an aspiration, and
///         there is no share-price inflation attack surface.
///       - Fees accrue per range via Q128 accumulators, checkpointed on every share change;
///         claims are pull-only. A claim fee (default 0) applies to FEES exclusively.
///       - The staking switch ships dormant: staked shares route their fee accrual to a
///         settable distributor instead of the holder. It costs nothing until used and
///         cannot be retrofitted later (contracts are immutable).
/// @dev The slice of the Voter this contract needs: does `account` back `poolId` with a lock it
///      owns? Declared here rather than importing the Voter so the hook does not carry the whole
///      voting contract in its bytecode, and so the two can be deployed in either order.
///
///      NO `IVoterEscrowRef` HERE. An interface of that name used to sit between this block and the
///      `IBallotGate` it describes, carrying a doc claiming to be the probe `setBallotGate` uses.
///      It was neither: it had no reference anywhere in this file, and `setBallotGate` deliberately
///      does the back-reference check with a RAW staticcall — because `try`/`catch` over an
///      interface is not enough here. A contract with a payable catch-all succeeds with empty
///      returndata, and the decode then reverts in the SUCCESS branch, past both catches.
///
///      That matters because the dead interface's doc read as an invitation to "tidy" the raw call
///      into `try IVoterEscrowRef(escrow).voter()`, which reopens exactly that hole on the setter
///      binding the anti-rental guarantee. Deleted for that reason, not for tidiness.
interface IBallotGate {
    /// @dev The escrow the gate is wired to. Read by `setBallotGate` to prove that THIS gate is the
    ///      one that escrow calls back — see the cross-check there.
    function ve() external view returns (address);
    function ballotBacks(address account, uint256 tokenId, PoolId poolId) external view returns (bool);
    // NEITHER IS REACHED BY ANY LEDGER PATH, and neither is probed by `setBallotGate`, which checks
    // the four that `stake`/`syncRanges` actually call. They are declared for integrators reading
    // this interface as the gate's shape.
    //
    // That is worth stating rather than leaving as a silent gap: the setter's own NatSpec records
    // that its probe once tracked `isGaugeLive` while `stake` had already moved to `isGaugeEarning`,
    // and staying on the old member reopened the hole. Two unreachable members sitting here are the
    // standing invitation to re-add the wrong probe, or to route a future `stake` gate through a
    // member nothing verifies exists.
    function isGaugeKilled(PoolId poolId) external view returns (bool);
    function isGaugeLive(PoolId poolId) external view returns (bool);
    function isGaugeEarning(PoolId poolId) external view returns (bool);
    function gaugeWeightNow(PoolId poolId) external view returns (uint256);
}

abstract contract FablesLedger is FablesBaseHook, ERC6909, ReentrancyGuardTransient, IUnlockCallback {
    using PoolIdLibrary for PoolKey;
    using CurrencyLibrary for Currency;

    error LedgerPaused();
    error DeskBelowMinWeight();
    error PauseTooLong();
    error ZeroLiquidity();
    /// @notice The transaction was mined after the caller's stated deadline.
    error DeadlineExpired();
    error InsufficientUnstakedShares();
    error ZeroShares();
    error ZeroAddress();
    error InvalidSink();
    // Reverted from inside `LedgerLib` on the admin paths, so they surface through this
    // contract with these selectors; declared here for that ABI surface and cost no bytecode.
    error InvalidClaimFee();
    error DistributorNotFFAware();
    error ClaimFeeAboveMax();
    error NothingToClaim();
    error NotAVoterOfThisPool();
    error BallotGateUnset();
    error DeskRetired();
    error InvalidBallotGate();
    error InvalidMsgValue();
    error RefundFailed();

    event Deposited(address indexed owner, uint256 indexed rangeId, uint128 liquidity);
    event Withdrawn(address indexed owner, uint256 indexed rangeId, uint128 liquidity);
    event FeesClaimed(address indexed owner, uint256 indexed rangeId, uint256 amount0, uint256 amount1);
    event Staked(address indexed owner, uint256 indexed rangeId, uint128 shares);
    // `FeesForgone` is declared in `LedgerTypes.sol`, so `LedgerLib` emits it with
    // the identical signature the settlement indexer reads.
    event Unstaked(address indexed owner, uint256 indexed rangeId, uint128 shares);
    // `FeesCollected` is declared in `LedgerTypes.sol` (with its full per-field settlement
    // rationale), so `LedgerLib.creditFees` emits it with the identical signature
    // the indexer reads.
    // `DistributorSwept` and `ClaimFeeSwept` are declared in `LedgerTypes.sol`, so
    // `LedgerLib`'s sweep functions emit them with the identical signatures the
    // indexer reads.
    event ClaimFeeSet(PoolId indexed poolId, uint16 bps, address recipient);
    event DistributorSet(address distributor);
    event FFFeeSinkSet(address sink);
    event PausedSet(uint256 pausedUntil);
    event PoolPausedSet(PoolId indexed poolId, uint256 pausedUntil);
    event BallotGateSet(address gate);

    /// @dev ALIASED from `LedgerLib`, not redeclared — the library is the one that enforces it, so
    ///      the two can no longer disagree. 20%, fixed in bytecode.
    uint16 public constant MAX_CLAIM_FEE_BPS = LedgerLib.MAX_CLAIM_FEE_BPS;
    /// @dev How far back a sync will walk the rate history. Beyond it the all-time minimum is
    ///      used, which can only ever charge LESS — never more — than the true window minimum.
    ///      This cap, not a cooldown, is what bounds the cost: it holds whatever the history
    ///      length. The AccessManager delay on the SETTERS makes growing the history slow as well,
    ///      but that is a second line and not this cap's warrant — and the routine grower is now
    ///      `setClaimFeeBps` on REVENUE_OPS, not `setClaimFee` on ADMIN. The whole point of that
    ///      split was to let the two carry different delays, so if REVENUE_OPS is ever moved to
    ///      delay 0 the second line goes and this cap is the only bound left. It is sized to be
    ///      sufficient alone.
    ///      ALIASED from `LedgerLib` for the same reason as `MAX_CLAIM_FEE_BPS` above.
    uint256 public constant MAX_CLAIM_FEE_WALK = LedgerLib.MAX_CLAIM_FEE_WALK;

    // `RangeState` now lives in `LedgerTypes.sol` (shared with `LedgerLib`); its layout is
    // unchanged. See that file for the per-field notes.

    // `UserPosition` now lives in `LedgerTypes.sol` (shared with `LedgerLib`); its layout is
    // unchanged. See that file for the per-field notes.

    /// @notice Admin levers. None of them can BLOCK a withdrawal — but two ARE read on that path.
    /// @dev `claimFeeRecipient`, and the per-pool rate in `_poolClaimFee`, are read on every
    ///      `withdraw`: `_withdrawTo` -> `_syncRange` -> `unlockCallback` -> `LedgerLib.creditFees`
    ///      -> `_split`, where `claimFeeRecipient != address(0)` gates the skim. So an admin write
    ///      changes the AMOUNT credited; it cannot stop the exit, which is the guarantee that
    ///      actually matters and the one this line used to overstate.
    ///
    ///      `withdrawAndClaim`'s own NatSpec says this correctly and at length ("a caller who
    ///      refuses a rate here and then withdraws pays exactly the rate they refused"), so the two
    ///      blocks answered the same question in opposite directions — the shape that let the
    ///      PoolManager sentinel be missed on three of four `take` paths in an earlier round. Two
    ///      lenses reported it independently.
    ///
    ///      `distributor`, `distributorFF` and `ffFeeSink` really are unread on that path.
    address public claimFeeRecipient;
    address public distributor;
    /// @notice The protocol token, cached from the distributor. Refused by `sweepDistributor`.
    address public distributorFF;
    /// @notice Destination for FF-denominated staked-fee revenue. See `sweepDistributor`.
    address public ffFeeSink;

    // `ClaimFeeChange` now lives in `LedgerTypes.sol` (shared with `LedgerLib`, which walks the
    // history inside `creditFees`); its layout is unchanged.

    /// @notice Every claim-fee rate this ledger has ever stood at, oldest first.
    /// @dev v4 accrues fees LAZILY: nothing is paid until a position is touched, so a range's
    ///      backlog is an opaque lump earned over a window of arbitrary length that may span any
    ///      number of rate changes. A single per-range snapshot could not describe that. It gave
    ///      `min(rate now, rate at last touch)`, which is right at both ends and wrong in the
    ///      middle — a rate that dipped and recovered between two touches billed the WHOLE
    ///      backlog at the high rate, including everything earned while the protocol was
    ///      advertising the low one.
    ///      Keyed by pool: one singleton may serve many pools, and a single hook-wide rate would
    ///      force every pool on it onto the same protocol fee. The recipient stays hook-wide (one
    ///      sink), and clearing it still zeroes every pool at once, because the effective rate is
    ///      `recipient == 0 ? 0 : bps` at every read.
    mapping(PoolId poolId => PoolClaimFee policy) internal _poolClaimFee;

    /// @notice How many rate changes had been recorded when each range last realized its fees —
    ///         i.e. where in the history its current backlog opened.
    /// @dev An INDEX, not a timestamp, and not a rate. Not a rate because a single rate cannot
    ///      answer "what was in force across this window". Not a timestamp because several rate
    ///      changes and several syncs can share one `block.timestamp`, and a cursor that cannot
    ///      order two events in the same block would charge a backlog at a rate that was set
    ///      after it was already realized.
    mapping(uint256 rangeId => uint64 index) public claimFeeSyncIndex;

    /// @notice Exploit-response switch: freezes deposits, claims, staking, transfers and
    ///         sweeps. Principal withdrawal and unstaking are deliberately NOT pausable, ever.
    /// @dev An expiry, not a flag. A pause that never lapses is indistinguishable from a
    ///      confiscation of everything it touches: fees already credited to a holder become
    ///      permanently unclaimable and a receipt becomes permanently untransferable, with no
    ///      recourse if the key that set it is gone. Bounding the duration in bytecode keeps
    ///      the emergency power without letting it become a permanent one — renewing is always
    ///      possible, but it is a deliberate, visible act each time rather than the default.
    uint256 public pausedUntil;

    /// @notice Per-pool freeze: deposits, claims, staking and transfers, scoped to one pool.
    /// @dev NOT the sweeps. `pausedUntil` also freezes `sweepDistributor` and `sweepClaimFee`, and
    ///      this cannot: both pots are keyed by CURRENCY and aggregate across every pool on the
    ///      singleton, so there is no pool in scope to test. An incident that touches the fee pots
    ///      themselves — rather than one pool's LP traffic — still needs the hook-wide `pause`.
